{{ config(materialized='table') }}
select oi.order_item_id, o.order_id, date_trunc('month', o.order_date)::date as order_month, o.order_date, o.channel_id, sc.channel_name, r.province, p.category, oi.quantity, oi.unit_price * oi.quantity * (1 - o.discount_pct / 100) as net_revenue, p.unit_cost * oi.quantity as cost_of_goods, oi.unit_price * oi.quantity * (1 - o.discount_pct / 100) - p.unit_cost * oi.quantity as gross_profit from {{ ref('stg_order_items') }} oi join {{ ref('stg_orders') }} o on o.order_id = oi.order_id join {{ ref('stg_customers') }} c on c.customer_id = o.customer_id join {{ ref('stg_regions') }} r on r.region_id = c.region_id join {{ ref('stg_products') }} p on p.product_id = oi.product_id join {{ ref('stg_sales_channels') }} sc on sc.channel_id = o.channel_id where o.status = 'Completed'
